"use client"

import * as React from "react"
import { cn } from "@/lib/utils"
import { MinecraftSurface } from "./minecraft-surface"
import { minecraftCardSprite } from "./minecraft-card-sprite"
import { MinecraftCardText, CardScaleContext } from "./minecraft-card-text"
import "./minecraft-card.css"

function Card({ className, scale = 2, style, children, ...props }: React.ComponentProps<"div"> & { scale?: 1 | 2 | 3 }) {
  return <div data-slot="card" className={cn("mc-card", className)} style={{ "--mc-scale": scale, ...style } as React.CSSProperties} {...props}>
    <MinecraftSurface sprite={minecraftCardSprite} /><CardScaleContext value={scale}>{children}</CardScaleContext>
  </div>
}
function CardHeader({ className, ...props }: React.ComponentProps<"div">) { return <div data-slot="card-header" className={cn("mc-card-header", className)} {...props} /> }
function CardTitle({ className, children, ...props }: React.ComponentProps<"div">) { return <div data-slot="card-title" className={cn("mc-card-title", className)} {...props}><MinecraftCardText bold>{children}</MinecraftCardText></div> }
function CardDescription({ className, children, ...props }: React.ComponentProps<"div">) { return <div data-slot="card-description" className={cn("mc-card-description", className)} {...props}><MinecraftCardText>{children}</MinecraftCardText></div> }
function CardAction({ className, ...props }: React.ComponentProps<"div">) { return <div data-slot="card-action" className={cn("mc-card-action", className)} {...props} /> }
function CardContent({ className, ...props }: React.ComponentProps<"div">) { return <div data-slot="card-content" className={cn("mc-card-content", className)} {...props} /> }
function CardFooter({ className, ...props }: React.ComponentProps<"div">) { return <div data-slot="card-footer" className={cn("mc-card-footer", className)} {...props} /> }
export { Card, CardHeader, CardTitle, CardDescription, CardAction, CardContent, CardFooter }

@layer theme, base, components, utilities;
@import "./minecraft-text-assets.css";
@layer components {
  .mc-card { --mc-pixel: calc(1px * var(--mc-scale, 2)); position: relative; isolation: isolate; box-sizing: border-box; display: flex; flex-direction: column; gap: calc(12 * var(--mc-pixel)); padding: calc(18 * var(--mc-pixel)); min-width: calc(12 * var(--mc-pixel)); color: #fff; font-family: "Minecraft Pilot 26.2", monospace; font-size: calc(8 * var(--mc-pixel)); line-height: calc(9 * var(--mc-pixel)); font-synthesis: none; border: 0; border-radius: 0; background: transparent; }
  .mc-card > .mc-surface { z-index: -1; }
  .mc-card-header { display: grid; grid-template-columns: minmax(0, 1fr); gap: calc(12 * var(--mc-pixel)); text-align: center; min-width: 0; }
  .mc-card-header:has(> [data-slot="card-action"]) { grid-template-columns: minmax(0, 1fr) auto; }
  .mc-card-action { grid-column: 2; grid-row: 1 / span 2; align-self: start; }
  .mc-card-title, .mc-card-description { min-width: 0; }
  .mc-card-content { min-width: 0; }
  .mc-card-footer { display: flex; align-items: center; justify-content: center; gap: calc(6 * var(--mc-pixel)); }
  .mc-card-footer > .mc-button { flex: 1; min-width: 0; }
  .mc-card-text { display: block; width: 100%; }
  .mc-card-text-line { display: block; height: calc(9 * var(--mc-pixel)); white-space: pre; text-align: left; }
  .mc-card-text-line > .mc-bitmap, .mc-card-bold { vertical-align: top; }
  .mc-card-bold, .mc-card-bold-pixels { display: inline-flex; }
  .mc-card-bold-pixels { filter: drop-shadow(var(--mc-pixel) var(--mc-pixel) 0 #3f3f3f); }
  .mc-card-bold-glyph { position: relative; display: block; flex-shrink: 0; width: calc(var(--mc-advance) * var(--mc-pixel)); height: calc(8 * var(--mc-pixel)); }
  .mc-card-bold-glyph > i { position: absolute; top: 0; left: 0; width: calc(8 * var(--mc-pixel)); height: calc(8 * var(--mc-pixel)); background: #fff; mask-image: var(--mc-ascii-atlas); mask-size: calc(128 * var(--mc-pixel)) calc(128 * var(--mc-pixel)); mask-position: calc(-1 * var(--mc-glyph-x) * var(--mc-pixel)) calc(-1 * var(--mc-glyph-y) * var(--mc-pixel)); mask-repeat: no-repeat; }
  .mc-card-bold-glyph > i + i { left: var(--mc-pixel); }
  .mc-card-accessible { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
}

import * as React from "react"
import { minecraftGlyphs } from "./minecraft-font"
import { MinecraftText } from "./minecraft-text"
export const CardScaleContext = React.createContext(2)

function wrap(text: string, width: number, bold: boolean) {
  const lines: string[] = []
  const advance = (char: string) => minecraftGlyphs[char.charCodeAt(0) - 32][2] + Number(bold)
  for (let remaining of text.split("\n")) {
    while (Array.from(remaining).reduce((sum, char) => sum + advance(char), 0) > width) {
      let count = 0, used = 0, space = -1
      while (count < remaining.length) {
        if (remaining[count] === " ") space = count
        const next = advance(remaining[count])
        if (used + next > width && count > 0) break
        used += next; count++
      }
      const end = space >= 0 ? space : Math.max(1, count)
      lines.push(remaining.slice(0, end))
      remaining = remaining.slice(end + Number(space >= 0))
    }
    lines.push(remaining)
  }
  return lines
}

export function MinecraftCardText({ children, bold = false }: { children: React.ReactNode; bold?: boolean }) {
  const scale = React.useContext(CardScaleContext)
  const node = React.useRef<HTMLSpanElement>(null)
  const [width, setWidth] = React.useState(200)
  React.useLayoutEffect(() => {
    const element = node.current
    if (!element) return
    const measure = () => {
      setWidth(Math.max(1, Math.floor(element.clientWidth / scale)))
    }
    measure()
    const observer = new ResizeObserver(measure)
    observer.observe(element)
    return () => observer.disconnect()
  }, [children, scale])
  if ((typeof children !== "string" && typeof children !== "number") || !/^[\x20-\x7e\n]*$/.test(String(children))) return <>{children}</>
  const lines = wrap(String(children), width, bold)
  const widths = lines.map(line => Array.from(line).reduce((sum, char) => sum + minecraftGlyphs[char.charCodeAt(0) - 32][2] + Number(bold), 0))
  const widest = Math.max(0, ...widths)
  return <span ref={node} className="mc-card-text" data-mc-card-text="true">{lines.map((line, index) => <span className="mc-card-text-line" key={index} style={{ paddingLeft: `calc(${Math.floor((width - widest) / 2) + Math.floor(widest / 2) - Math.floor(widths[index] / 2)} * var(--mc-pixel))` }}>
    {bold ? <span className="mc-bitmap mc-card-bold"><span className="mc-card-bold-pixels" aria-hidden="true">{Array.from(line, (char, i) => {
      const [x, y, advance] = minecraftGlyphs[char.charCodeAt(0) - 32]
      return <span className="mc-card-bold-glyph" key={i} style={{ "--mc-advance": advance + 1, "--mc-glyph-x": x, "--mc-glyph-y": y, visibility: char === " " ? "hidden" : undefined } as React.CSSProperties}><i /><i /></span>
    })}</span><span className="mc-card-accessible">{line}</span></span> : <MinecraftText>{line}</MinecraftText>}
  </span>)}</span>
}

import * as React from "react"
import "./minecraft-surface.css"

type Sprite = { width: number; height: number; border: { left: number; top: number; right: number; bottom: number }; stretch: boolean; image: string; pieces: readonly string[] }

function MinecraftSurface({ sprite }: { sprite: Sprite }) {
  const widths = [sprite.border.left, sprite.width - sprite.border.left - sprite.border.right, sprite.border.right]
  const heights = [sprite.border.top, sprite.height - sprite.border.top - sprite.border.bottom, sprite.border.bottom]
  return <span aria-hidden="true" className="mc-surface" style={{
    gridTemplateColumns: `calc(${widths[0]} * var(--mc-pixel)) minmax(0, 1fr) calc(${widths[2]} * var(--mc-pixel))`,
    gridTemplateRows: `calc(${heights[0]} * var(--mc-pixel)) minmax(0, 1fr) calc(${heights[2]} * var(--mc-pixel))`,
  } as React.CSSProperties}>
    {sprite.pieces.map((piece, index) => <span key={index} style={{ backgroundImage: piece,
      backgroundSize: sprite.stretch && (index % 3 === 1 || Math.floor(index / 3) === 1) ? "100% 100%" : `calc(${widths[index % 3]} * var(--mc-pixel)) calc(${heights[Math.floor(index / 3)]} * var(--mc-pixel))`,
    }} />)}
  </span>
}
export { MinecraftSurface }

@layer theme, base, components, utilities;
@layer components {
  .mc-surface {
    position: absolute;
    inset: 0;
    display: grid;
    pointer-events: none;
    image-rendering: pixelated;
  }
  .mc-surface > span { background-repeat: repeat; }
}

import * as React from "react"
import { minecraftGlyphs } from "./minecraft-font"
import "./minecraft-text.css"

function MinecraftText({ children, className }: { children: React.ReactNode; className?: string }) {
  if ((typeof children !== "string" && typeof children !== "number") || !/^[\x20-\x7e]*$/.test(String(children))) return <span className={className}>{children}</span>
  const text = String(children)
  return <span className={`mc-bitmap ${className ?? ""}`}>
    <span className="mc-text-pixels" aria-hidden="true">{Array.from(text, (char, index) => {
      const [x, y, advance] = minecraftGlyphs[char.charCodeAt(0) - 32]
      return <span key={index} className="mc-glyph" style={{ "--mc-glyph-x": x, "--mc-glyph-y": y, "--mc-advance": advance, visibility: char === " " ? "hidden" : undefined } as React.CSSProperties} />
    })}</span>
    <span className="mc-text-accessible">{text}</span>
  </span>
}
export { MinecraftText }

@layer theme, base, components, utilities;
@import "./minecraft-text-assets.css";
@layer components {
  .mc-bitmap { display: inline-flex; image-rendering: pixelated; --mc-pixel: calc(1px * var(--mc-scale, 2)); }
  .mc-bitmap > .mc-text-pixels { display: inline-flex; filter: drop-shadow(var(--mc-pixel) var(--mc-pixel) 0 var(--mc-shadow, #3f3f3f)); }
  .mc-bitmap .mc-glyph {
    display: block;
    width: calc(var(--mc-advance) * var(--mc-pixel));
    height: calc(8 * var(--mc-pixel));
    flex-shrink: 0;
    background-color: var(--mc-ink, #fff);
    mask-image: var(--mc-ascii-atlas);
    mask-size: calc(var(--mc-atlas-size) * var(--mc-pixel)) calc(var(--mc-atlas-size) * var(--mc-pixel));
    mask-position: calc(-1 * var(--mc-glyph-x) * var(--mc-pixel)) calc(-1 * var(--mc-glyph-y) * var(--mc-pixel));
    mask-repeat: no-repeat;
  }
  .mc-bitmap > .mc-text-accessible { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
}
